{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-sp1tQZ/src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, with the tie-breaking rule
 * that prefers matches that come earliest.
 */

/**
 * Finds the matched line pairs between `base` and `side` using a longest
 * common subsequence over whole lines compared as exact strings. When
 * several subsequences of the maximal length exist, the one whose matches
 * come earliest is chosen: walking both documents from the start, a match
 * is taken whenever the two current lines are equal, and otherwise the side
 * whose remaining subsequence is at least as long as the other's is
 * advanced, with ties preferring to advance the base.
 *
 * @param {string[]} base the base document
 * @param {string[]} side the other document
 * @returns {[number, number][]} pairs of matched indices `[baseIndex, sideIndex]`
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = []
  for (let i = 0; i <= n; i++) dp.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}
"}

