 * Three-way merge: turns mine, base and theirs into a list of stable
 * regions and changed regions, each resolved against the base.
 */

import { lcsMatches } from './lcs.js'

/**
 * Describes a single side's change against the base: the base lines it
 * replaces and the side's lines that replace them.
 *
 * @param {string[]} base the base document
 * @param {string[]} side the other document
 * @param {'mine'|'theirs'} source which side this change came from
 * @returns {{source: 'mine'|'theirs', baseStart: number, baseEnd: number, lines: string[]}[]}
 */
function changesFor(base, side, source) {
  const matches = lcsMatches(base, side)
  const changes = []
  let bi = 0
  let si = 0
  for (const [mi, mj] of matches) {
    if (mi > bi || mj > si) changes.push({ source, baseStart: bi, baseEnd: mi, lines: side.slice(si, mj) })
    bi = mi + 1
    si = mj + 1
  }
  if (bi < base.length || si < side.length) {
    changes.push({ source, baseStart: bi, baseEnd: base.length, lines: side.slice(si, side.length) })
  }
  return changes
}

/**
 * Reconstructs one side's lines across a region: the base lines the
 * region's changes on that side start before, their own lines, base lines
 * between successive changes of the same side, and the base lines the
 * region's changes on that side end before.
 *
 * @param {string[]} base the base document
 * @param {{start: number, end: number, changes: object[]}} region the region
 * @param {'mine'|'theirs'} source which side to reconstruct
 * @returns {string[]} the side's lines for the region
 */
function sideLines(base, region, source) {
  const changes = region.changes.filter(c => c.source === source).sort((a, b) => a.baseStart - b.baseStart)
  const out = []
  let pos = region.start
  for (const change of changes) {
    if (change.baseStart > pos) out.push(...base.slice(pos, change.baseStart))
    out.push(...change.lines)
    pos = change.baseEnd
  }
  if (pos < region.end) out.push(...base.slice(pos, region.end))
  return out
}

/**
 * Splits the base document into an ordered list of stable and changed
 * regions, given the changes gathered from both sides.
 *
 * @param {string[]} base the base document
 * @param {object[]} allChanges changes from both sides, sorted by base
 *   start with mine before theirs when starts are equal
 * @returns {({type: 'stable', lines: string[]}|{type: 'region', mine: string[], base: string[], theirs: string[]})[]}
 */
function buildItems(base, allChanges) {
  const regions = []
  let idx = 0
  while (idx < allChanges.length) {
    const first = allChanges[idx]
    const region = { start: first.baseStart, end: first.baseEnd, changes: [first] }
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= region.end) {
      region.changes.push(allChanges[idx])
      region.end = Math.max(region.end, allChanges[idx].baseEnd)
      idx++
    }
    regions.push(region)
  }

  const items = []
  let pos = 0
  for (const region of regions) {
    if (region.start > pos) items.push({ type: 'stable', lines: base.slice(pos, region.start) })
    items.push({
      type: 'region',
      mine: sideLines(base, region, 'mine'),
      base: base.slice(region.start, region.end),
      theirs: sideLines(base, region, 'theirs'),
    })
    pos = region.end
  }
  if (pos < base.length) items.push({ type: 'stable', lines: base.slice(pos, base.length) })

  return items
}

/**
 * Computes the ordered list of stable and changed regions for a three-way
 * merge of `mine` and `theirs` against `base`.
 *
 * @param {string[]} mine mine's document
 * @param {string[]} base the base document
 * @param {string[]} theirs their document
 * @returns {({type: 'stable', lines: string[]}|{type: 'region', mine: string[], base: string[], theirs: string[]})[]}
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = changesFor(base, mine, 'mine')
  const theirsChanges = changesFor(base, theirs, 'theirs')
  const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)
  return buildItems(base, allChanges)
}

/**
 * Resolves a changed region's mine/base/theirs lines to a single verdict.
 *
 * @param {{mine: string[], base: string[], theirs: string[]}} region a
 *   changed region
 * @returns {{kind: 'mine'|'theirs'|'both'|'conflict'}} the resolution: for
 *   `mine`, `theirs` and `both` the region resolves cleanly (to mine's
 *   lines, theirs' lines, and either side's equal lines, respectively); for
 *   `conflict` the three line arrays are irreconcilable
 */
export function resolveRegion(region) {
  const equal = (a, b) => a.length === b.length && a.every((line, i) => line === b[i])
  if (equal(region.mine, region.theirs)) return { kind: 'both' }
  if (equal(region.mine, region.base)) return { kind: 'theirs' }
  if (equal(region.theirs, region.base)) return { kind: 'mine' }
  return { kind: 'conflict' }
}
"}

